import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Calculate effect sizes for all features
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic
            effect_sizes.append((fid, abs(mean_diff), abs(t_stat)))

    # Sort by t-statistic descending
    effect_sizes.sort(key=lambda x: x[2], reverse=True)

    # Select top features avoiding near-duplicates
    selected = []
    excluded = set()

    # Use first 3 features as candidates
    candidates = effect_sizes[:3]

    for fid, _, _ in candidates:
        if fid in excluded:
            continue
        selected.append(fid)

        # Exclude correlated features (r >= 0.6)
        for other_fid in feats.ids:
            if other_fid == fid or other_fid in excluded:
                continue
            col1 = feats.column(fid)
            col2 = feats.column(other_fid)
            corr = abs(np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1])
            if corr >= 0.6:
                excluded.add(other_fid)

        if len(selected) >= MAX_DRIVERS:
            break

    # If no clear mechanism, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # For small model, use just top 2 features
    columns = tuple(selected[:2])

    # Simple interaction: only one product term
    products = ()
    if len(columns) >= 2:
        products = ((columns[0], columns[1]),)

    # Create weighted score from selected features
    loadings = {}
    for i, fid in enumerate(columns):
        loadings[fid] = 1.0 / (i + 1)  # inverse ranking weights

    # Return the design
    return Design(
        drivers=columns[:1],  # Most promising feature as driver
        columns=columns,
        products=products,
        loadings=loadings
    )

